    def opposition_based_learning(self, individual, lb, ub):
        return lb + ub - individual

    def adaptive_mutation(self, a, b, c, diversity):
        mutation_factor = 0.4 + 0.6 * np.random.rand() * (1.0 - diversity)
        return a + mutation_factor * (b - c)

    def __call__(self, func):
